const s = readLine().trim();
const q = parseInt(readLine());
const n = s.length;
const P1 = 94905991, P2 = 94905989;   // below sqrt(2^53) so products stay exact
const B1 = 1000 + Math.floor(Math.random() * (P1 - 2000));
const B2 = 1000 + Math.floor(Math.random() * (P2 - 2000));
const h1 = new Array(n + 1).fill(0), h2 = new Array(n + 1).fill(0);
const p1 = new Array(n + 1).fill(1), p2 = new Array(n + 1).fill(1);
for (let i = 0; i < n; i++) {
  const c = s.charCodeAt(i);
  h1[i + 1] = (h1[i] * B1 + c) % P1;
  h2[i + 1] = (h2[i] * B2 + c) % P2;
  p1[i + 1] = (p1[i] * B1) % P1;
  p2[i + 1] = (p2[i] * B2) % P2;
}
function get(l, r) {
  const ln = r - l + 1;
  const x = ((h1[r] - (h1[l - 1] * p1[ln]) % P1) % P1 + P1) % P1;
  const y = ((h2[r] - (h2[l - 1] * p2[ln]) % P2) % P2 + P2) % P2;
  return x * P2 + y;   // < 2^53, unique per pair
}
const out = [];
for (let i = 0; i < q; i++) {
  const [a, b, c, d] = readLine().trim().split(/\s+/).map(Number);
  out.push(get(a, b) === get(c, d) ? 'YES' : 'NO');
}
console.log(out.join('\n'));

