import java.util.*;
import java.io.*;

public class Main {
    static final long M1 = 1_000_000_007L, M2 = 998_244_353L;
    static long[] h1, h2, p1, p2;

    static long get(int l, int r) {
        int ln = r - l + 1;
        long x = ((h1[r] - h1[l - 1] * p1[ln]) % M1 + M1) % M1;
        long y = ((h2[r] - h2[l - 1] * p2[ln]) % M2 + M2) % M2;
        return x * M2 + y;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int q = Integer.parseInt(br.readLine().trim());
        int n = s.length();
        Random rnd = new Random();
        long B1 = 1000 + rnd.nextInt((int) M1 - 2000);
        long B2 = 1000 + rnd.nextInt((int) M2 - 2000);
        h1 = new long[n + 1]; h2 = new long[n + 1];
        p1 = new long[n + 1]; p2 = new long[n + 1];
        p1[0] = 1; p2[0] = 1;
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i);
            h1[i + 1] = (h1[i] * B1 + c) % M1;
            h2[i + 1] = (h2[i] * B2 + c) % M2;
            p1[i + 1] = p1[i] * B1 % M1;
            p2[i + 1] = p2[i] * B2 % M2;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            StringTokenizer tk = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(tk.nextToken()), b = Integer.parseInt(tk.nextToken());
            int c = Integer.parseInt(tk.nextToken()), d = Integer.parseInt(tk.nextToken());
            sb.append(get(a, b) == get(c, d) ? "YES" : "NO").append('\n');
        }
        System.out.print(sb);
    }
}

