#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll M1 = 1000000007LL, M2 = 998244353LL;
vector<ll> h1, h2, p1, p2;
pair<ll, ll> get(int l, int r) {
    int ln = r - l + 1;
    ll x = ((h1[r] - h1[l - 1] * p1[ln]) % M1 + M1) % M1;
    ll y = ((h2[r] - h2[l - 1] * p2[ln]) % M2 + M2) % M2;
    return {x, y};
}
int main() {
    string s;
    int q;
    cin >> s >> q;
    int n = s.size();
    mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());
    ll B1 = 1000 + rng() % (M1 - 2000), B2 = 1000 + rng() % (M2 - 2000);
    h1.assign(n + 1, 0); h2.assign(n + 1, 0);
    p1.assign(n + 1, 1); p2.assign(n + 1, 1);
    for (int i = 0; i < n; i++) {
        h1[i + 1] = (h1[i] * B1 + s[i]) % M1;
        h2[i + 1] = (h2[i] * B2 + s[i]) % M2;
        p1[i + 1] = p1[i] * B1 % M1;
        p2[i + 1] = p2[i] * B2 % M2;
    }
    while (q--) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        cout << (get(a, b) == get(c, d) ? "YES" : "NO") << "\n";
    }
    return 0;
}
